[MemoryDiagnoser]
[SimpleJob(BenchmarkDotNet.Engines.RunStrategy.ColdStart, launchCount: 1)]
public class OrderQueryBenchmarks
{
    private AppDbContext _db = null!;

    [GlobalSetup]
    public void Setup()
    {
        _db = TestDbContextFactory.Create();
    }

    [Benchmark(Baseline = true)]
    public async Task<List<Order>> EagerLoading()
    {
        return await _db.Orders
            .Include(o => o.Customer)
            .Include(o => o.Items)
            .ToListAsync();
    }

    [Benchmark]
    public async Task<List<Order>> ProjectionQuery()
    {
        return await _db.Orders
            .Select(o => new OrderDto
            {
                Id = o.Id,
                CustomerName = o.Customer.Name,
                ItemCount = o.Items.Count
            })
            .ToListAsync();
    }
}
